function persistShapeLibrary(next){customShapes=saveShapeLibrary(next);if(defaults.customShape){defaults.customShape=customShapes.find(item=>item.id===defaults.customShape.id)||null;}renderInspector();}
function saveSelectedCustom(){const object=find(selected);if(object?.type!=='shape'||object.shape!=='custom')return;if(customShapes.length>=SHAPE_LIBRARY_LIMIT){notify(`My Shapes can hold up to ${SHAPE_LIBRARY_LIMIT} shapes.`);return}const requested=prompt('Name this custom shape',`Custom shape ${customShapes.length+1}`);if(requested===null)return;try{const entry=templateFromShape(object,uniqueShapeName(requested,customShapes));persistShapeLibrary([...customShapes,entry]);object.templateId=entry.id;defaults.customShape=entry;notify(`Saved “${entry.name}” to My Shapes.`);render();}catch(error){notify(error.message)}}
function useSavedShape(id){const entry=customShapes.find(item=>item.id===id);if(!entry)return;defaults.customShape=entry;Object.assign(defaults,entry.style,{shape:'custom'});clearSelection();setTool('shape');notify(`Drag to place “${entry.name}”.`);}
function editShapeLibrary(action,id){const entry=customShapes.find(item=>item.id===id);if(!entry)return;if(action==='rename'){const requested=prompt('Rename saved shape',entry.name);if(requested===null)return;entry.name=uniqueShapeName(requested,customShapes,entry.id);persistShapeLibrary(customShapes);notify('Saved shape renamed.');return}if(action==='delete'&&confirm(`Delete “${entry.name}” from My Shapes?`)){persistShapeLibrary(customShapes.filter(item=>item.id!==id));notify('Saved shape removed.')}}
$('inspector').addEventListener('click',e=>{const shape=e.target.closest('[data-shape]'),drawCustom=e.target.closest('[data-draw-custom]'),saved=e.target.closest('[data-saved-shape]'),save=e.target.closest('[data-save-custom]'),libraryAction=e.target.closest('[data-shape-library-action]'),route=e.target.closest('[data-arrow-route]'),heads=e.target.closest('[data-arrow-heads]');if(save){saveSelectedCustom();return}if(libraryAction){editShapeLibrary(libraryAction.dataset.shapeLibraryAction,libraryAction.dataset.shapeId);return}if(saved){useSavedShape(saved.dataset.savedShape);return}if(drawCustom){defaults.customShape=null;defaults.shape='custom';clearSelection();setTool('shape');notify('Draw a closed silhouette on the canvas.');return}if(shape){defaults.customShape=null;const object=find(selected);if(object)delete object.templateId;updateShape('shape',shape.dataset.shape);}if(route){const o=find(selected),value=route.dataset.arrowRoute;if(o?.type==='arrow'&&editable(board,o))mutate(()=>o.route=value);else{defaults.route=value;board.arrowRoute=value;renderInspector();}}if(heads){const o=find(selected),value=arrowheadFlags(heads.dataset.arrowHeads).mode;if(o?.type==='arrow'&&editable(board,o))mutate(()=>o.heads=value);else{defaults.heads=value;renderInspector();}}});

const hsvHex=(h,s=.78,v=.88)=>{const f=n=>{const k=(n+h/60)%6;return v-v*s*Math.max(0,Math.min(k,4-k,1))},hex=n=>Math.round(n*255).toString(16).padStart(2,'0');return '#'+hex(f(5))+hex(f(3))+hex(f(1));};
$('inspector').addEventListener('pointerdown',e=>{const wheel=e.target.closest('[data-color-wheel]');if(!wheel)return;e.preventDefault();wheel.setPointerCapture(e.pointerId);let chosen;const pick=event=>{const r=wheel.getBoundingClientRect(),angle=(Math.atan2(event.clientY-r.top-r.height/2,event.clientX-r.left-r.width/2)*180/Math.PI+90+360)%360,color=hsvHex(angle);chosen=color;wheel.style.setProperty('--current',color);wheel.querySelector('span').style.transform=`translate(-50%) rotate(${angle}deg) translateY(-25px)`;updateDrawing('color',color,true);};pick(e);const move=event=>pick(event),up=event=>{pick(event);wheel.removeEventListener('pointermove',move);wheel.removeEventListener('pointerup',up);updateDrawing('color',chosen);};wheel.addEventListener('pointermove',move);wheel.addEventListener('pointerup',up);});

$('inspector').addEventListener('change',e=>{const prop=e.target.dataset.prop;if(!prop)return;const o=find(selected);if(o&&!editable(board,o))return;let value=e.target.value;if(['fontSize','stroke'].includes(prop)){value=Number(value);if(!Number.isFinite(value))return;value=prop==='fontSize'?Math.max(12,Math.min(160,value)):Math.max(1,Math.min(20,value))}if(prop==='bold')value=value==='true';if(o)mutate(()=>{o[prop]=value;if(prop==='fontSize'){o.h=o.fontSize*1.35+8;contain(board,o)}});else{defaults[prop]=value;renderInspector()}});
function deleteSelection(){const objects=selectionObjects();if(!objects.length||objects.some(object=>!editable(board,object)))return;mutate(()=>{for(const object of objects)removeObject(board,object.id);clearSelection();arrowStart=null;})}
function duplicateSelection(){const objects=selectionObjects();if(!objects.length||objects.some(object=>!editable(board,object)))return;mutate(()=>{const copies=[],idMap=new Map();for(const object of objects.filter(object=>object.type!=='arrow')){const values=clone(object);delete values.id;values.x+=30;values.y+=30;board.activeLayer=object.layer;const copy=addObject(board,values);idMap.set(object.id,copy.id);copies.push(copy.id);}for(const object of objects.filter(object=>object.type==='arrow')){const values=clone(object);delete values.id;for(const endpoint of ['start','end']){values[endpoint]={...values[endpoint],x:(values[endpoint].x||0)+30,y:(values[endpoint].y||0)+30};if(idMap.has(values[endpoint].objectId))values[endpoint].objectId=idMap.get(values[endpoint].objectId);}values.controlPoints=(values.controlPoints||[]).map(point=>({x:point.x+30,y:point.y+30}));board.activeLayer=object.layer;copies.push(addObject(board,values).id);}setSelection(copies);})}
function performSelectionAction(action){if(action==='delete')deleteSelection();if(action==='duplicate')duplicateSelection();if(action==='back'||action==='front'){const objects=selectionObjects();if(objects.length&&objects.every(object=>editable(board,object)))mutate(()=>{const ids=new Set(objects.map(object=>object.id)),chosen=board.objects.filter(object=>ids.has(object.id)),others=board.objects.filter(object=>!ids.has(object.id));board.objects=action==='front'?[...others,...chosen]:[...chosen,...others];})}}
