async function insertImages(files,p=center()){finishText();if(!available())return;const layer=board.activeLayer;let offset=0;for(const file of files){if(!file.type.startsWith('image/')){notify('Choose an image file.');continue}const src=URL.createObjectURL(file);try{const image=new Image();image.src=src;await image.decode();if(!image.naturalWidth||!image.naturalHeight)throw new Error('Invalid image');const ratio=Math.min(1,380/image.naturalWidth,380/image.naturalHeight),w=Math.max(20,image.naturalWidth*ratio),h=Math.max(20,image.naturalHeight*ratio);mutate(()=>{board.activeLayer=layer;selected=addObject(board,{type:'image',x:p.x-w/2+offset,y:p.y-h/2+offset,w,h,src,name:file.name||'Pasted image'}).id});offset+=28;}catch{URL.revokeObjectURL(src);notify('This image could not be opened. Try PNG, JPG, or WebP.')}}setTool('select');}
