document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable]'))return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return}if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateSelection();return}if(e.code==='Space'){e.preventDefault();space=true;viewport.classList.add('space-pan');return}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelection();return}if(e.key==='Escape'){if(gesture?.before)board=gesture.before;gesture=null;viewport.classList.remove('panning');arrowStart=null;clearSelection();selectionMode='point';setTool('select');return}if(e.key==='Home'){e.preventDefault();centerCanvas();notify('Returned to the canvas center.');return}if(e.shiftKey&&e.code==='Digit1'){e.preventDefault();fit();return}if(mod||e.altKey)return;const tools={v:'select',h:'hand',t:'text',a:'arrow',p:'pen'};if(tools[e.key.toLowerCase()]){clearSelection();setTool(tools[e.key.toLowerCase()])}if(e.key.toLowerCase()==='i'&&available())$('image-input').click();const objects=selectionObjects();if(objects.length&&objects.every(object=>editable(board,object))&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();mutate(()=>{const step=e.shiftKey?10:1,dx=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0,dy=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;for(const object of objects){moveObjectBy(object,dx,dy);if(object.type!=='arrow')contain(board,object);}})}});
